import logging
import os
from functools import partial

from ute_common_abstract_core.network_elem_factory import NetworkElementFactory
from ute_common_abstract_core.network_elem_identification import MsgSourceIdentificationFactory, \
    MsgSourceIdentification, UeIdentification
from ute_common_abstract_core.network_elem_validator import NetworkElementValidator
from ta_ue_plugin_rtg.messaging.backend import Backend
from ta_ue_plugin_rtg.messaging.data_stream import RtgMmiLogDataStream, RtgMmiDataStream
from moler.config import devices
from robot.libraries.BuiltIn import BuiltIn
from ta_ue_plugin_rtg.messaging import TA_MESSAGING_BACKEND_PORT


# To allow for replaying Rtg MMI from log (troubleshooting) we want to be able to say:
#   "for given UE please do replay it from log and don't try to connect Rtg Mmi via ssh+telnet"
# Format of following configuration is:
#   UE-name: log-filename
# example:
#   UE_1: uesim_data_telnet_output.txt
#   UE_2: uesim_data_stream.txt
#   UE_3: uex_data_stream.txt
ue_logs_config = {}
cell_logs_config = {}
mmi_data_streams = {}


def rtg_message_source_recipe(variant, network_elem_type, id_of_network_element):
    """Recipe how to create message source"""
    for data_stream in _create_data_stream(str(id_of_network_element)):
        msg_src_class_fullname = 'ta_ue_plugin_rtg.messaging.message_source.RtgMessageSource'
        msg_src_constructor_params = {'data_stream': data_stream, 'variant': variant}
        yield msg_src_class_fullname, msg_src_constructor_params


def register_message_source(variant):
    """Register recipe 'how to build RtgMessageSource' for ta_messaging usage"""
    NetworkElementFactory().register_construction(element2create='message_source',
                                                  network_elem_type='UE',
                                                  variant=variant,
                                                  construction_generator=partial(rtg_message_source_recipe, variant, 'UE'))

    NetworkElementFactory().register_construction(element2create='message_source',
                                                  network_elem_type='UE_GROUP',
                                                  variant=variant,
                                                  construction_generator=partial(rtg_message_source_recipe, variant, 'UE_GROUP'))

    NetworkElementFactory().register_construction(element2create='message_source',
                                                  network_elem_type='CELL',
                                                  variant=variant,
                                                  construction_generator=partial(rtg_message_source_recipe, variant, 'CELL'))

    NetworkElementFactory().register_construction(element2create='message_source',
                                                  network_elem_type='MME',
                                                  variant=variant,
                                                  construction_generator=partial(rtg_message_source_recipe, variant, 'MME'))


def ensure_valid_ue_id(id_of_variant):
    """
    :param id_of_variant: id of UE to convert
    :return: converted UE id
    """
    rtg_ue_id = int(id_of_variant)  # expect digit; raises ValueError if other chars
    return rtg_ue_id


def ensure_int_pair_id(id_of_variant):
    """
    :param id_of_variant: id of UE to convert
    :return: converted UE id
    """
    assert len(id_of_variant) == 2
    id_1 = id_of_variant[0]
    id_2 = id_of_variant[1]
    rtg_id_1 = int(id_1)
    rtg_id_2 = int(id_2)
    return [rtg_id_1, rtg_id_2]


def register_variant_id_validators(variant):
    """Register validator function"""
    NetworkElementValidator().register_validator(name_of_element2validate='id_of_variant',
                                                 network_elem_type='UE',
                                                 variant=variant,
                                                 validator_function=ensure_valid_ue_id)

    NetworkElementValidator().register_validator(name_of_element2validate='id_of_variant',
                                                 network_elem_type='CELL',
                                                 variant=variant,
                                                 validator_function=ensure_valid_ue_id)

    NetworkElementValidator().register_validator(name_of_element2validate='id_of_variant',
                                                 network_elem_type='UE_GROUP',
                                                 variant=variant,
                                                 validator_function=ensure_int_pair_id)


def create_msg_src_id(variant, identifiers, network_elem_type, _specific_for_tool):
    """Create msg src id"""
    MsgSourceIdentification(identifiers=[(variant, variant.upper())], network_elem_type=network_elem_type, specific_for_tool=variant)
    return UeIdentification.from_type_id_pairs(identifiers=identifiers, specific_for_tool=variant)


def register_msg_src_id_constructor(variant):
    """Register msg src id"""
    MsgSourceIdentificationFactory().register_construction(network_elem_type='UE',
                                                           variant=variant,
                                                           msg_src_id_constructor=partial(create_msg_src_id, variant))


def plugin_rtg_message_source():
    """Register message source and its validator"""
    for variant in ['rtg', 'cus']:
        register_message_source(variant)
        register_variant_id_validators(variant)
        register_msg_src_id_constructor(variant)


def _create_data_stream(device_name):
    """
    Create data stream for UE

    either RtgMmiLogDataStream - if "UEs replayed from logs" configuration has such UE
    else RtgMmiDataStream
    """
    try:
        data_stream_log_of_ue = get_log_for_ue_name(device_name)
        data_stream = RtgMmiLogDataStream(log_filename=data_stream_log_of_ue, play_log_start_delay=1)
        yield data_stream
    except KeyError:  # no ue_name in "UEs replayed from logs" configuration
        Backend().run_startup_func(TA_MESSAGING_BACKEND_PORT)
        for mmi_name in _available_msg_sources():
            if mmi_name in mmi_data_streams:
                data_stream = mmi_data_streams[mmi_name]
            else:
                data_stream = RtgMmiDataStream(device_name=mmi_name)
                mmi_data_streams[mmi_name] = data_stream
            logging.getLogger('messaging').info('{} used by {}'.format(data_stream, device_name))
            yield data_stream


def _start_uexgate_if_needed():
    try:
        ta_uexgate_instance = BuiltIn().get_library_instance('ta_uexgate')
        if ta_uexgate_instance is not None and not ta_uexgate_instance._uexgate_started:
            logging.getLogger('messaging').info('ta_uexgate library detected. Running startup procedure')
            ta_uexgate_instance._run_startup_procedure()
    except Exception:
        logging.getLogger('messaging').info('ta_uexgate is not running')


def _available_msg_sources():
    msg_sources = []
    connection_hops = {'CONNECTION_HOPS': {'UNIX_LOCAL': {
        'UNIX_REMOTE': {'execute_command': 'telnet', 'command_params': {'host': Backend().get_ip(),
                                                                        'port': TA_MESSAGING_BACKEND_PORT,
                                                                        'login': '',
                                                                        'password': '',
                                                                        'expected_prompt': 'connected to uex log sink',
                                                                        'allowed_newline_after_prompt': True,
                                                                        'set_timeout': False}}},
        'UNIX_REMOTE': {
            'UNIX_LOCAL': {"execute_command": "exit_telnet", "required_command_params": [], "command_params": {"expected_prompt": r'^moler_bash#'}}}}}

    devices.define_device(name='UEX_GENSUB_SERVER',
                          device_class='moler.device.unixremote.UnixRemote',
                          connection_desc={'variant': 'threaded', 'io_type': 'terminal'},
                          connection_hops=connection_hops,
                          initial_state='UNIX_LOCAL')
    msg_sources.append('UEX_GENSUB_SERVER')
    return msg_sources


def get_log_for_ue_name(ue_name):
    """Return full path to UE stream"""
    if ue_name not in ue_logs_config:
        raise KeyError("logfile for {} not defined in RtgMessageSource configuration".format(ue_name))
    stream_full_path = ue_logs_config[ue_name]
    return stream_full_path


def set_log_for_ue_name(ue_name, log_filename):
    """Register full path to UE stream"""
    if ue_name.startswith("UE_") and os.path.exists(log_filename):
        ue_logs_config[ue_name] = log_filename


def clear_ue_from_logs_config():
    """Clear "UEs replayed from logs" configuration"""
    ue_logs_config.clear()
